\section{比例导航制导律设计方案}

\subsection{系统建模}
\begin{itemize}
    \item \textbf{坐标系}: 采用拦截器坐标系，目标沿直线飞行，拦截器在R=0时精确拦截目标。
    \item \textbf{目标运动}: 目标沿直线飞行，加速度为零，速度为 $v_t$。
    \item \textbf{拦截器运动}: 拦截器采用比例导航制导律，法向加速度为 $a_n = N' \dot{\lambda}$，其中 $\dot{\lambda}$ 为视线角速率。
\end{itemize}

\subsection{控制器选型}
\begin{itemize}
    \item \textbf{制导律}: 采用比例导航制导律，法向加速度为 $a_n = N' \dot{\lambda}$。
    \item \textbf{参数整定}: 稳态视线角速率误差为零，要求 $\dot{\lambda} \to 0$。最大法向加速度约束为 $|a_n| \le 3 a_t$。
\end{itemize}

\subsection{性能验证}
\begin{itemize}
    \item \textbf{拦截条件}: 拦截器在R=0时精确拦截目标，满足所有工程约束。
    \item \textbf{仿真验证}: 采用数值仿真验证制导律性能，确保拦截精度和稳定性。
\end{itemize}

\subsection{工程考量}
\begin{itemize}
    \item \textbf{传感器噪声}: 考虑视线角测量噪声，采用卡尔曼滤波估计视线角速率。
    \item \textbf{飞行器动态模型}: 考虑拦截器动力学模型，确保制导律在实际应用中稳定可靠。
\end{itemize}

\section{结论}
\begin{itemize}
    \item \textbf{方案}: 采用比例导航制导律，参数整定满足稳态视线角速率误差为零，最大法向加速度不超过目标加速度的3倍，制导参数N'恒定。
    \item \textbf{性能}: 拦截器在R=0时精确拦截目标，满足所有工程约束。
    \item \textbf{优势}: 比例导航制导律简单、鲁棒，易于实现。
\end{itemize}

\section{基于Lyapunov约束的MPC控制器设计}

\subsection{系统建模与控制目标}

\subsubsection{AUV动力学模型}
AUV的运动学方程(3)为：
\begin{equation}
\dot{\eta} = J(\eta) \nu
\end{equation}
\begin{equation}
M \dot{\nu} + C(\nu) \nu + D(\nu) \nu + g(\eta) = \tau
\end{equation}
其中，$\eta \in \mathbb{R}^6$为位置与姿态，$\nu \in \mathbb{R}^6$为线速度与角速度，$\tau \in \mathbb{R}^6$为推力。

\subsubsection{推力分配与约束}
推力分配关系为：
\begin{equation}
\tau = B \tau_s
\end{equation}
其中，$\tau_s \in \mathbb{R}^3$为推力向量，满足 $\|\tau_s\|_2 \le \tau_{max}=500N$。

\subsubsection{控制目标}
设计LMPC控制器，使得AUV跟踪轨迹 $\eta_d(t)$，满足：
\begin{itemize}
    \item 闭环稳定：Lyapunov函数 $V(\eta - \eta_d) \to 0$。
    \item 跟踪误差：$\|\eta - \eta_d\| \le 0.05\|\eta_d\|$ 在 $t \le 5s$ 内。
    \item 鲁棒性：对建模误差具有鲁棒性。
\end{itemize}

\subsection{Lyapunov约束MPC设计}

\subsubsection{Lyapunov函数选择}
选择二次型Lyapunov函数：
\begin{equation}
V(\tilde{\eta}) = \frac{1}{2} \tilde{\eta}^T P \tilde{\eta}
\end{equation}
其中，$\tilde{\eta} = \eta - \eta_d$， $P=P^T>0$。

\subsubsection{Lyapunov约束条件}
要求 $\dot{V}(\tilde{\eta}) < 0$，即：
\begin{equation}
\tilde{\eta}^T P \dot{\tilde{\eta}} + \frac{1}{2} \tilde{\eta}^T \dot{P} \tilde{\eta} < 0
\end{equation}
在MPC框架下，将此条件转化为约束优化问题，通过调整预测时域和权重矩阵，确保约束满足。

\subsection{控制器选型与参数整定}

\subsubsection{MPC优化问题}
在预测时域 $N_p$ 内，求解以下优化问题：
\begin{equation}
\min_{\tau_s(k)} \sum_{i=k}^{k+N_p-1} \left( \|\tilde{\eta}(i)\|_Q^2 + \|\tau_s(i)\|_R^2 \right)
\end{equation}
约束条件：
\begin{itemize}
    \item 动力学约束：$\eta(i+1) = f(\eta(i), \tau_s(i))$
    \item Lyapunov约束：$\dot{V}(\tilde{\eta}(i)) < 0$
    \item 推力约束：$\|\tau_s(i)\|_2 \le 500N$
\end{itemize}

\subsubsection{参数整定}
\begin{itemize}
    \item $N_p=10$：预测时域设置为10个采样周期。
    \item $Q=10I, R=0.1I$：权重矩阵，平衡跟踪误差与控制输入。
    \item $P$矩阵：通过LMI求解，确保Lyapunov稳定性。
\end{itemize}

\subsection{性能验证与工程考量}

\subsubsection{仿真验证}
在仿真中，设置轨迹跟踪误差为10%，观察控制器是否能在5秒内收敛至5%以内。通过加入建模误差和传感器噪声，验证鲁棒性。

\subsubsection{工程考量}
\begin{itemize}
    \item 实时性：采用基于C++的实时求解器，确保计算时间小于采样周期。
    \item 鲁棒性增强：引入自适应Lyapunov函数，实时调整Lyapunov函数参数以应对不确定性。
\end{itemize}

\section{结论}
该LMPC控制器通过Lyapunov约束确保闭环稳定性，满足推力饱和约束，并通过参数整定和鲁棒性设计，实现了AUV的轨迹跟踪控制。
